 home:{label:'Beranda',title:'Proper Energy — Energi yang bertumbuh bersama Anda',description:'Solusi PLTS Tumbuh dan platform inteligensi energi untuk rumah, installer, dan pengelola fleet. Mulai dengan perencanaan yang tepat.',group:'main'},
