const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<span aria-hidden="true">↗</span>';
const line=(a,b)=>`<div class="eyebrow-row"><span>${a}</span><span>${b}</span></div>`;
const btn=(text,href,alt=false)=>`<a class="${alt?'btn-secondary':'btn-primary'}" href="${href}"><span>${text}</span>${arrow}</a>`;
const WA=(subject='Halo Proper Energy, saya ingin berkonsultasi tentang PLTS.')=>'https://wa.me/'+COMPANY.whatsapp+'?text='+encodeURIComponent(subject);
const eyebrow=(text)=>`<span class="kicker"><i aria-hidden="true"></i>${text}</span>`;
const section=(id,title,intro,body,dark=false)=>`<section id="${id}" class="section ${dark?'section-dark':''}"><div class="wrap">${line(id.toUpperCase(),dark?'PROPER ENERGY':'DIRANCANG DENGAN TELITI')}<div class="section-heading"><h2>${title}</h2><p>${intro}</p></div>${body}</div></section>`;
const feature=(num,title,description,href='#',tag='SOLUSI')=>`<a class="feature-card" href="${href}"><div class="feature-top"><span>${num}</span><span>${tag}</span></div><div class="feature-icon" aria-hidden="true">${['↗','⌁','✳','◫','⚑','◌'][Number(num.replace(/\D/g,''))%6]||'↗'}</div><h3>${title}</h3><p>${description}</p><span class="feature-link">Pelajari lebih jauh ${arrow}</span></a>`;
const miniCta=(title,sub,cta='Diskusikan Kebutuhan Anda')=>`<section class="section cta-zone"><div class="wrap"><div class="cta-panel">${eyebrow('LANGKAH NYATA · BERSAMA PROPER ENERGY')}<h2>${title}</h2><p>${sub}</p><div class="actions">${btn(cta,PATHS.kontak)}${btn('Jelajahi dashboard demo','/demo/',true)}</div></div></div></section>`;
function packages(){const items=[['Starter','3.15','5','1 × 5.12','75.000.000','starter'],['Safer','5.04','8','2 × 5.12','105.000.000','safer'],['Signature','7.56','12','4 × 5.12','159.000.000','signature']];return `<div class="packages-grid">${items.map(([name,kwp,panels,bat,price,id],i)=>`<article class="package ${i===1?'highlight':''}"><div class="package-head"><span>0${i+1} / PLTS TUMBUH</span><span>${i===1?'PILIHAN FAVORIT':'RESIDENSIAL'}</span></div><h3>${name}</h3><p>${['Mulai dari fondasi yang tepat dan dapat ditingkatkan.','Perluas produksi sekaligus kapasitas penyimpanan.','Prioritaskan kebutuhan energi dan backup yang lebih besar.'][i]}</p><div class="package-cap"><strong>${kwp}</strong><span>kWp<br/>daya panel nominal</span></div><dl><div><dt>Panel 630 Wp</dt><dd>${panels} modul</dd></div><div><dt>Inverter</dt><dd>5 kW</dd></div><div><dt>Baterai nominal</dt><dd>${bat} kWh</dd></div></dl><div class="package-price"><small>HARGA REFERENSI</small><strong>Rp ${price}</strong></div><a class="package-link" href="${PATHS[id]}">Lihat detail paket ${arrow}</a></article>`).join('')}</div><p class="disclaimer">Harga referensi untuk contoh PLN 3.500 VA, instalasi 1 fase Jabodetabek, berdasarkan informasi brosur v1.0 Juni 2026 di properenergy.id. Penawaran aktual, termasuk ketentuan pajak dan kondisi lapangan, harus dikonfirmasi setelah survei.</p>`;}
function dashboard(){return `<div class="dash-preview"><div class="dash-top"><div class="dash-controls"><span class="dot"></span><span class="dot"></span><span class="dot"></span></div><span>PROPER ENERGY / STUDIO OPERASIONAL</span><span class="dash-mode">SIMULASI · BUKAN DATA FISIK</span></div><div class="dash-main"><aside class="dash-side"><b>PE</b><span class="sel">◫</span><span>⌁</span><span>▥</span><span>⚑</span></aside><div class="dash-content"><div class="dash-overline">OPERASI ARMADA / RINGKASAN</div><h3>Aset Terpantau. Masalah Terhalau.</h3><div class="dash-kpis"><div><span>PRODUKSI HARI INI</span><strong>218.4<small> kWh</small></strong></div><div><span>LOKASI AKTIF</span><strong>14<small> / 16</small></strong></div><div><span>PERLU TINDAKAN</span><strong>04<small> aktif</small></strong></div></div><div class="dash-visual"><div class="plot"><span>KINERJA ENERGI <small>SAMPEL 7 HARI</small></span><svg viewBox="0 0 560 200" preserveAspectRatio="none" role="img" aria-label="Ilustrasi grafik performa produksi energi"><g stroke="#dae4de" stroke-width="1"><path d="M0 30H560M0 80H560M0 130H560M0 180H560"/></g><path d="M0 172 C48 160 75 58 120 83S210 167 269 97 366 30 423 92 500 134 560 48" stroke="#247b57" stroke-width="5" fill="none" stroke-linecap="round"/></svg></div><div class="issue"><small>ANTREAN OPERATOR</small><b>Tinjau Terlebih Dahulu.</b><p>Gateway offline<br/>Perlu inspeksi teknisi</p><span>1 KRITIS ↗</span></div></div></div></div></div>`;}
function energyFlow(){return `<div class="energy-map"><div class="energy-map-head"><span>ALIRAN DAYA · SIMULASI</span><span>DIPERBARUI PER SKENARIO · BUKAN TELEMETRI FISIK</span></div><div class="energy-nodes"><div class="energy-node"><span class="node-icon">☼</span><small>PANEL SURYA</small><strong id="flow-solar">5.20 <em>kW</em></strong><small>produksi DC</small></div><div class="energy-arrow">→</div><div class="energy-node central"><span class="node-icon">↯</span><small>INVERTER</small><strong id="flow-inverter">5.05 <em>kW</em></strong><small>keluaran AC</small></div><div class="energy-arrow">→</div><div class="energy-node"><span class="node-icon">⌂</span><small>BEBAN RUMAH</small><strong id="flow-load">2.40 <em>kW</em></strong><small>konsumsi daya</small></div></div><div class="energy-bottom"><div><span>▣</span><div><small>ARUS BATERAI</small><strong id="flow-battery">+2.65 kW</strong></div></div><div><span>≋</span><div><small>IMPOR LISTRIK PLN</small><strong id="flow-grid">0.00 kW</strong></div></div></div><div class="energy-time" role="group" aria-label="Pilih skenario waktu"><button class="time-btn" data-time="pagi" aria-pressed="false">Pagi 08:00</button><button class="time-btn selected" data-time="siang" aria-pressed="true">Siang 12:30</button><button class="time-btn" data-time="sore" aria-pressed="false">Sore 16:30</button><button class="time-btn" data-time="malam" aria-pressed="false">Malam 20:00</button></div></div>`;}
function hero(title,sub,{kicker='PROPER ENERGY · INDONESIA',dark=false,visual=true,image='/assets/hero-solar-home.jpg',action='Jelajahi Solusi',href=PATHS.tumbuh,back='KEMANDIRIAN ENERGI'}={}){return `<section class="subhero ${dark?'dark':''}"><div class="wrap"><div class="subhero-top"><span>${kicker}</span><span>${back}</span></div><div class="subhero-grid"><div>${eyebrow('DIRANCANG UNTUK KEHIDUPAN SEHARI-HARI')}<h1>${title}</h1><p>${sub}</p><div class="actions">${btn(action,href)}${btn('Jadwalkan konsultasi',PATHS.kontak,true)}</div></div>${visual?`<div class="subhero-art" style="overflow:hidden;border-radius:20px;box-shadow:0 24px 48px rgba(0,0,0,0.25);border:1px solid rgba(255,255,255,0.1);"><img src="${image}" alt="Dokumentasi PLTS Proper Energy" width="710" height="520" style="width:100%;height:100%;object-fit:cover;display:block;" loading="lazy"/></div>`:''}</div></div></section>`;}
function keypoints(items){return `<div class="number-points">${items.map(([a,b],i)=>`<div><span>0${i+1}</span><h3>${a}</h3><p>${b}</p></div>`).join('')}</div>`;}
